class Employee:
    def __init__(self, name, salary):
        self.name = name
        self.salary = salary

    def pay(self):
        return self.salary

class Manager(Employee):
    def __init__(self, name, salary, bonus):
        super().__init__(name, salary)
        self.bonus = bonus

    def pay(self):
        return super().pay() + self.bonus

staff = [Employee('Ece', 30000), Manager('Mert', 45000, 8000)]
for e in staff:
    print(e.name, e.pay())
print('Total:', sum(e.pay() for e in staff))
